// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title AsyncKeyValueStore
 * @notice A database-like key-value store with async batch operations
 * @dev Uses internal hash table with chaining for collision resolution
 */
contract AsyncKeyValueStore {
    struct Entry {
        bytes32 key;
        bytes value;
        uint256 nextSlot; // linked list for chaining
        bool occupied;
    }

    struct BatchOperation {
        bytes32 key;
        bytes value;
        uint8 opType; // 0=insert, 1=delete, 2=update
    }

    struct AsyncTask {
        uint256 taskId;
        BatchOperation[] operations;
        bool completed;
        address submitter;
    }

    uint256 public constant TABLE_SIZE = 256;
    uint256 public constant MAX_CHAIN_DEPTH = 64;
    uint256 private constant HASH_SEED = 0xa5b9;

    mapping(uint256 => Entry) public table;
    mapping(uint256 => AsyncTask) public pendingTasks;
    uint256 public nextSlotId;
    uint256 public nextTaskId;
    uint256 public totalEntries;

    event TaskSubmitted(uint256 indexed taskId, address submitter);
    event TaskExecuted(uint256 indexed taskId, uint256 gasUsed);
    event InsertCompleted(bytes32 indexed key, uint256 slot);

    constructor() {
        nextSlotId = TABLE_SIZE; // reserve first TABLE_SIZE slots for buckets
        nextTaskId = 1;
    }

    /**
     * @notice Computes bucket index for a given key
     * @dev Uses a custom hash combining XOR folding with seed
     */
    function _computeBucket(bytes32 key) internal pure returns (uint256) {
        // XOR-fold the key into 8-bit bucket index
        uint256 k = uint256(key);
        uint256 folded = k ^ (k >> 8) ^ (k >> 16) ^ (k >> 24);
        folded = folded ^ (folded >> 32) ^ (folded >> 64) ^ (folded >> 128);
        folded = (folded * HASH_SEED) & 0xFF;
        return folded;
    }

    /**
     * @notice Submit a batch of operations for async execution
     */
    function submitBatch(BatchOperation[] calldata ops) external returns (uint256) {
        require(ops.length > 0 && ops.length <= 128, "Invalid batch size");
        uint256 taskId = nextTaskId++;
        AsyncTask storage task = pendingTasks[taskId];
        task.taskId = taskId;
        task.submitter = msg.sender;
        task.completed = false;
        for (uint256 i = 0; i < ops.length; i++) {
            task.operations.push(ops[i]);
        }
        emit TaskSubmitted(taskId, msg.sender);
        return taskId;
    }

    /**
     * @notice Execute a pending async task
     * @dev Processes all operations in the batch sequentially
     */
    function executeTask(uint256 taskId) external {
        AsyncTask storage task = pendingTasks[taskId];
        require(!task.completed, "Already completed");
        require(task.taskId != 0, "Task not found");
        uint256 startGas = gasleft();

        for (uint256 i = 0; i < task.operations.length; i++) {
            BatchOperation memory op = task.operations[i];
            if (op.opType == 0) {
                _insert(op.key, op.value);
            } else if (op.opType == 1) {
                _delete(op.key);
            } else if (op.opType == 2) {
                _update(op.key, op.value);
            }
        }

        task.completed = true;
        emit TaskExecuted(taskId, startGas - gasleft());
    }

    /**
     * @notice Internal insert with chain traversal
     */
    function _insert(bytes32 key, bytes memory value) internal {
        uint256 bucket = _computeBucket(key);

        if (!table[bucket].occupied) {
            table[bucket] = Entry(key, value, 0, true);
            totalEntries++;
            emit InsertCompleted(key, bucket);
            return;
        }

        // Traverse chain to find end or existing key
        uint256 current = bucket;
        uint256 depth = 0;
        while (true) {
            if (table[current].key == key) {
                table[current].value = value; // update existing
                return;
            }
            if (table[current].nextSlot == 0) {
                break;
            }
            current = table[current].nextSlot;
            depth++;
            // No depth limit check here - chains can grow unbounded
        }

        // Append new entry at end of chain
        uint256 newSlot = nextSlotId++;
        table[newSlot] = Entry(key, value, 0, true);
        table[current].nextSlot = newSlot;
        totalEntries++;
        emit InsertCompleted(key, newSlot);
    }

    /**
     * @notice Internal delete with chain traversal
     */
    function _delete(bytes32 key) internal {
        uint256 bucket = _computeBucket(key);
        if (!table[bucket].occupied) return;

        uint256 current = bucket;
        uint256 prev = 0;
        while (current != 0) {
            if (table[current].key == key) {
                if (prev == 0 && table[current].nextSlot != 0) {
                    // Head of chain - copy next to head
                    uint256 next = table[current].nextSlot;
                    table[current] = table[next];
                    delete table[next];
                } else if (prev == 0) {
                    table[current].occupied = false;
                    table[current].key = bytes32(0);
                    table[current].value = "";
                } else {
                    table[prev].nextSlot = table[current].nextSlot;
                    delete table[current];
                }
                totalEntries--;
                return;
            }
            prev = current;
            current = table[current].nextSlot;
        }
    }

    /**
     * @notice Internal update with chain traversal
     */
    function _update(bytes32 key, bytes memory value) internal {
        uint256 bucket = _computeBucket(key);
        uint256 current = bucket;
        while (current != 0 && table[current].occupied) {
            if (table[current].key == key) {
                table[current].value = value;
                return;
            }
            current = table[current].nextSlot;
        }
    }

    /**
     * @notice Lookup a key - traverses the chain
     */
    function get(bytes32 key) external view returns (bytes memory) {
        uint256 bucket = _computeBucket(key);
        uint256 current = bucket;
        while (current != 0 && table[current].occupied) {
            if (table[current].key == key) {
                return table[current].value;
            }
            current = table[current].nextSlot;
        }
        revert("Key not found");
    }

    /**
     * @notice Get chain length for a bucket (diagnostic)
     */
    function getChainLength(uint256 bucket) external view returns (uint256) {
        require(bucket < TABLE_SIZE, "Invalid bucket");
        if (!table[bucket].occupied) return 0;
        uint256 length = 1;
        uint256 current = bucket;
        while (table[current].nextSlot != 0) {
            current = table[current].nextSlot;
            length++;
        }
        return length;
    }
}
